//! Structural and golden guards for `--emit-header` (`ui_data.h`).
//!
//! The goldens in `tests/golden/` are the output of
//! `emit_ui.py --ui-json` (the reference implementation) for the same pages, so
//! comparing the generated bytes proves the Rust writer did not silently
//! change formatting, conditionals or values.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

fn exe() -> &'static str {
    env!("CARGO_BIN_EXE_frontend-rust")
}

fn temp_dir(name: &str) -> PathBuf {
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join(name);
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    dir
}

/// Runs the binary and returns the exact bytes of `ui_data.h`.
fn run_header(
    dir: &Path,
    html: &Path,
    css: &Path,
    width: u32,
    height: u32,
    extra: &[&str],
) -> Vec<u8> {
    let header = dir.join("ui_data.h");
    let mut command = Command::new(exe());
    command
        .arg("--html")
        .arg(html)
        .arg("--css")
        .arg(css)
        .arg("--width")
        .arg(width.to_string())
        .arg("--height")
        .arg(height.to_string())
        .arg("--emit-ui")
        .arg(dir.join("ui.json"))
        .arg("--emit-header")
        .arg(&header);
    for arg in extra {
        command.arg(arg);
    }
    let Output {
        status,
        stderr,
        stdout,
    } = command.current_dir(dir).output().unwrap();
    assert!(
        status.success(),
        "frontend-rust failed\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&stdout),
        String::from_utf8_lossy(&stderr),
    );
    fs::read(&header).unwrap()
}

fn emit(dir: &Path, html: &str, css: &str, extra: &[&str]) -> String {
    fs::write(dir.join("index.html"), html).unwrap();
    fs::write(dir.join("style.css"), css).unwrap();
    let bytes = run_header(
        dir,
        &dir.join("index.html"),
        &dir.join("style.css"),
        320,
        200,
        extra,
    );
    String::from_utf8(bytes).unwrap()
}

/// Byte comparison that reports the first difference instead of dumping both
/// whole headers.
fn assert_same_bytes(actual: &[u8], expected: &[u8], label: &str) {
    if actual == expected {
        return;
    }
    let end = actual.len().min(expected.len());
    let index = (0..end)
        .find(|index| actual[*index] != expected[*index])
        .unwrap_or(end);
    let line = 1 + expected[..index].iter().filter(|byte| **byte == b'\n').count();
    panic!(
        "{label}: first difference at byte {index} (expected line {line}); \
         actual {} bytes, golden {} bytes",
        actual.len(),
        expected.len(),
    );
}

/// Small page that uses none of the E1 fields and has no `<input>`: no extras
/// block, no document include and no `kUiInputs` table.
#[test]
fn header_without_extras_or_inputs() {
    let dir = temp_dir("emit_header_plain");
    let header = emit(
        &dir,
        "<!doctype html><html><head><link rel=\"stylesheet\" href=\"style.css\"></head><body><div class=\"a\">Hola</div></body></html>",
        ".a { width: 100px; height: 20px; }",
        &[],
    );
    // body.root + div.a + text.
    assert!(header.contains("#define UI_NODE_COUNT 3"), "{header}");
    assert!(header.contains("#define UI_VIEWPORT_WIDTH 320"));
    assert!(header.contains("#define UI_VIEWPORT_HEIGHT 200"));
    assert!(!header.contains("UI_STYLE_EXTRAS"), "{header}");
    assert!(!header.contains("int text_align;"));
    assert!(!header.contains("wn_document_format.h"));
    assert!(!header.contains("kUiInputs"));
    assert!(!header.contains("R2_NODE_INPUT"));
    assert!(header.ends_with("#endif /* UI_DATA_H */\n"), "{header}");
}

/// `* { box-sizing: border-box }` makes every node use an E1 field, so the
/// struct gains the seven fields and every node line the seven values.
#[test]
fn header_with_extras() {
    let dir = temp_dir("emit_header_extras");
    let header = emit(
        &dir,
        "<!doctype html><html><head><link rel=\"stylesheet\" href=\"style.css\"></head><body><div class=\"a\">Hola</div></body></html>",
        "* { box-sizing: border-box; } .a { width: 100px; }",
        &[],
    );
    assert!(header.contains("#define UI_STYLE_EXTRAS 1"), "{header}");
    assert!(header.contains("int box_sizing;"));
    assert!(header.contains("float flex_basis;"));
    // Node line tail: box_sizing, flex_grow, flex_shrink, flex_basis.
    assert!(header.contains(", 0, 0.0000f, 0, 1, 0.0000f, 1.0000f, -1.0000f, "));
}

/// Regression for the extras predicate: Python reads
/// `float(node.get("flex_basis") or -1.0) >= 0.0`, so a zero basis is falsy and
/// must NOT enable the extras block (`flex-basis: 0px` / `flex: 0 1 0`).
/// Comparing the whole header against the Python golden also proves the printer
/// was not touched.
#[test]
fn flex_basis_zero_does_not_enable_extras() {
    let dir = temp_dir("emit_header_flex_basis_zero");
    let header = emit(
        &dir,
        "<!doctype html>\n<html>\n<head><link rel=\"stylesheet\" href=\"style.css\"></head>\n<body>\n  <div class=\"a\">A</div>\n  <div class=\"b\">B</div>\n</body>\n</html>\n",
        ".a { flex-basis: 0px; }\n.b { flex: 0 1 0; }\n",
        &[],
    );
    assert!(!header.contains("UI_STYLE_EXTRAS"), "{header}");
    assert!(!header.contains("int flex_basis;"));
    assert_same_bytes(
        header.as_bytes(),
        include_bytes!("golden/flex_basis_zero.h"),
        "flex-basis 0",
    );
}

/// The canonical runtime page header, checked in as generated by
/// `emit_ui.py --ui-json` for 960x640.
#[test]
fn canonical_page_matches_golden_header() {
    let dir = temp_dir("emit_header_canonical");
    let page = Path::new(env!("CARGO_MANIFEST_DIR")).join("../runtime/page");
    let bytes = run_header(
        &dir,
        &page.join("index.html"),
        &page.join("style.css"),
        960,
        640,
        &[],
    );
    assert_same_bytes(
        &bytes,
        include_bytes!("golden/canonical.h"),
        "canonical page",
    );
}

/// `<input type="text">` under `--pilot` adds `R2_NODE_INPUT`, the document
/// include, `UI_INPUT_COUNT` and the `kUiInputs` table.
#[test]
fn header_with_input() {
    let dir = temp_dir("emit_header_input");
    let header = emit(
        &dir,
        "<!doctype html><html><head><link rel=\"stylesheet\" href=\"style.css\"></head><body><input type=\"text\" maxlength=\"8\" placeholder=\"Buscar\"></body></html>",
        "input { width: 200px; height: 24px; }",
        &["--pilot"],
    );
    assert!(header.contains("R2_NODE_INPUT"), "{header}");
    assert!(header.contains("#include \"document/wn_document_format.h\""));
    assert!(header.contains("#define UI_INPUT_COUNT 1"));
    assert!(header.contains("kUiInputs[UI_INPUT_COUNT > 0 ? UI_INPUT_COUNT : 1]"));
    // body.root + input.
    assert!(header.contains("#define UI_NODE_COUNT 2"), "{header}");
    assert!(header.contains("    { 1, \"\", \"Buscar\", 8, 0 },"), "{header}");
}
